steps.text:
/*
	VIOC_airfields.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "airfields". Se compila en todas las maquinas desde init.sqf (la funcion de servicio local tiene que existir
	donde es local la aeronave); todo lo demas corre solo en el servidor.

	Parametros de lobby:
	  VIOC_AIRFIELDS    1 = servicio en aerodromos propios y regreso a base de la IA (por defecto), 0 = no.
	  VIOC_AF_DEFENSES  1 = antiaereas, antitanque y ametralladora extra en cada aerodromo (por defecto), 0 = no.
	  VIOC_AF_PARKED    2 = aeronaves enemigas estacionadas + despegue de alerta (por defecto), 1 = solo estacionadas, 0 = no.

	1) Tabla de aerodromos (VIOC_AF_TABLE), leida en el juego de configFile >> "CfgWorlds" >> worldName: el principal
	   (ilsPosition, ilsDirection, ilsTaxiIn, ilsTaxiOff) y cada clase de SecondaryAirports, en el orden del config.
	   ID de landAt = ese orden si el ID esta en allAirports; se verifica en el juego: cuando un avion aterriza con un ID,
	   se mira cual aerodromo de la tabla le queda mas cerca y se guarda (VIOC_AF_IDSEEN) para corregir el mapeo.
	   Duenio = el bando del pueblo mas cercano (a menos de VIOC_AF_OWNER_RANGE) a los puntos del aerodromo.
	   Mapas sin aeropuertos o con ilsPosition [0,0]: tabla vacia, el script no hace nada.
	2) Servicio (cada 5 s) para las aeronaves del bando duenio (IA y jugadores; las vacias con cti_net del bando) que
	   estan en el suelo, casi quietas, en la zona del aerodromo (a menos de VIOC_AF_ZONE_TAXI de un punto de rodaje o
	   en la franja de la pista o a menos de VIOC_AF_ZONE_APRON de la plataforma) y sin enemigos a menos de VIOC_AF_SAFE: combustible y danio por pasos (en la maquina
	   donde la aeronave es local), y a los VIOC_AF_REARM_AFTER s quieta, rearme con la funcion de la mision
	   (CTI_CO_FNC_RearmVehicle, que ademas aplica SanitizeAircraft). Gratis. Aviso en pantalla para el piloto jugador.
	   Los helicopteros tambien reciben servicio junto a la fabrica aerea o el HQ propios.
	   Se borra cti_ai_lastpos de la tripulacion en cada pasada: el control de atascados de update_ai.fsm no los teletransporta.
	3) Regreso a base (cada 15 s) de las aeronaves IA de Oeste y Este (equipos IA de update_ai.fsm y otros grupos IA;
	   nunca grupos con jugadores, operaciones especiales, alerta ni UAV) con poco combustible, mucho danio, una pieza
	   critica rota o poca municion: al aerodromo propio no disputado mas cercano (aviones con landAt; helicopteros a un
	   helipuerto invisible libre con land "LAND"; los helicopteros tambien a la base). El grupo queda con
	   vioc_air_busy = true: update_ai.fsm no le da ordenes nuevas ni compras mientras tanto (ganchos en el FSM) y su
	   hilo de orden actual se corta (cti_order_seed nuevo). Al terminar el servicio (o a los plazos) se libera con
	   cti_team_reload = true y la IA vuelve a su orden.
	4) Defensas: hasta 2 AA + 1 AT + 1 MG por aerodromo con duenio, en los extremos de pista y la plataforma a menos de
	   VIOC_AF_DEF_RANGE del centro del pueblo duenio (para que la mision las tripule al activarse el pueblo), fuera de la
	   pista y del rodaje. Son ayudantes cti_defense_kind agregados a cti_town_defenses: la mision crea la estatica de la
	   faccion duenia (listas CTI_<lado>_Defenses_*), la tripula, la cambia al capturar y fortifications le pone nido.
	5) Estacionadas: aeronaves VACIAS y cerradas (lock 2, VIOC_AF_parked = true) del duenio, solo en aerodromos de
	   bandos sin jugadores humanos (nunca aviones gratis para el bando del jugador). Oeste/Este: su lista de compra aerea
	   filtrada por su mejora aerea; guerrilla: sus listas de pueblo o su faccion, si no tiene ninguna, nada.
	   Topes: principal 2 helicopteros + 2 aviones, los demas 1 + 1, VIOC_AF_PARK_TOTAL en todo el mapa. Aparecen solo sin
	   jugadores a menos de VIOC_AF_PARK_PLAYER_RANGE ni enemigos a menos de VIOC_AF_PARK_ENEMY_RANGE: al inicio una por
	   minuto hasta el tope, despues una cada VIOC_AF_PARK_REFILL s; tras un cambio de duenio, a los VIOC_AF_PARK_AFTER_CAPTURE s.
	   Al cambiar de duenio: las del duenio anterior se borran (si hay un jugador a menos de 300 m, quedan sin combustible y
	   cerradas y se borran cuando se aleja). Los restos destruidos se borran a los 10 min sin jugadores cerca.
	   No se guardan en la partida (gancho en Server_SaveToProfile.sqf).
	6) Alerta (VIOC_AF_PARKED = 2): si atacan un aerodromo con helicoptero estacionado, uno recibe tripulacion y despega
	   contra los atacantes; a los VIOC_AF_SCR_TIME s (o sin enemigos 2 min) vuelve, aterriza y se estaciona de nuevo.
	   1 por aerodromo, VIOC_AF_SCR_MAX en el mapa, VIOC_AF_SCR_COOLDOWN s de espera, y solo si el presupuesto de IA lo
	   permite (VIOC_PERF_AI_COUNT / VIOC_PERF_AI_MAX de perf_cleanup si existen; si no, cuenta allUnits contra VIOC_AF_AI_MAX_DEFAULT).
	Listas del servidor: VIOC_AF_TABLE, VIOC_AF_PARKLIST, VIOC_AF_RTB, VIOC_AF_SCR (VIOC_AF_PARKED es el parametro de lobby).
	Consola (LOCAL EXEC en el anfitrion): hint (call VIOC_AF_fnc_info); [0] call VIOC_AF_fnc_forceParked;
	[vehicle player] call VIOC_AF_fnc_forceRTB; [0] call VIOC_AF_fnc_forceScramble. VIOC_AF_INFO = [servicios, rtb, rtb_ok, aparcadas, borradas, alertas].
*/

//--- Ajustes
VIOC_AF_PERIOD = 5;               // s por pasada del bucle (servicio); duenios y regreso a base cada 3 pasadas
VIOC_AF_OWNER_RANGE = 1500;       // m: pueblo duenio de un aerodromo
VIOC_AF_ZONE_TAXI = 110;          // m alrededor de cada punto de rodaje o ILS
VIOC_AF_ZONE_RWY = 60;            // m a cada lado del eje de la pista
VIOC_AF_ZONE_APRON = 230;         // m alrededor de la plataforma (alli aterrizan los helicopteros que vuelven)
VIOC_AF_BASE_RANGE = 230;         // m alrededor de la fabrica aerea o el HQ propio (solo helicopteros)
VIOC_AF_SAFE = 300;               // m sin enemigos alrededor de la aeronave que recibe servicio
VIOC_AF_FUEL_STEP = 0.05;         // combustible por pasada (de vacio a lleno en 100 s)
VIOC_AF_REPAIR_STEP = 0.08;       // danio menos por pieza y pasada
VIOC_AF_REARM_AFTER = 30;         // s quieta antes del rearme
VIOC_AF_RTB_FUEL = 0.25;
VIOC_AF_RTB_DAMAGE = 0.45;
VIOC_AF_RTB_AMMO = 0.15;
VIOC_AF_RTB_TIMEOUT = 600;        // s para aterrizar
VIOC_AF_SVC_MAX = 300;            // s maximos de servicio en tierra
VIOC_AF_RTB_COOLDOWN = 600;       // s antes de otro regreso de la misma aeronave
VIOC_AF_DEST_SAFE = 500;          // m sin enemigos alrededor del aerodromo de destino
VIOC_AF_DEF_RANGE = 650;          // m: defensas a esta distancia como maximo del centro del pueblo duenio
VIOC_AF_PARK_TOTAL = 10;
VIOC_AF_PARK_MAIN = [2, 2];       // [helicopteros, aviones] en el aerodromo principal del mapa
VIOC_AF_PARK_OTHER = [1, 1];
VIOC_AF_PARK_PLAYER_RANGE = 1500;
VIOC_AF_PARK_ENEMY_RANGE = 500;
VIOC_AF_PARK_REFILL = 1200;
VIOC_AF_PARK_AFTER_CAPTURE = 900;
VIOC_AF_SCR_COOLDOWN = 900;
VIOC_AF_SCR_TIME = 600;
VIOC_AF_SCR_MAX = 2;
VIOC_AF_SCR_ENEMIES = 3;
VIOC_AF_SCR_RANGE = 900;
VIOC_AF_AI_MAX_DEFAULT = 650;     // tope de IA vivas si perf_cleanup no publica VIOC_PERF_AI_MAX
if (isNil "VIOC_AF_INFO") then {VIOC_AF_INFO = [0, 0, 0, 0, 0, 0]};

VIOC_AF_fnc_svcOn = {(missionNamespace getVariable ["VIOC_AIRFIELDS", 1]) > 0};
VIOC_AF_fnc_defOn = {(missionNamespace getVariable ["VIOC_AF_DEFENSES", 1]) > 0};
VIOC_AF_fnc_parkMode = {missionNamespace getVariable ["VIOC_AF_PARKED", 2]};

//--- Donde la aeronave es local (se llama directo o por remoteExec): un paso de combustible y de reparacion.
VIOC_AF_fnc_svcLocal = {
	params ["_v", "_fs", "_rs"];
	if (!alive _v || {!local _v}) exitWith {};
	if ((fuel _v) < 1) then {_v setFuel (((fuel _v) + _fs) min 1)};
	private _hd = (getAllHitPointsDamage _v) param [2, []];
	private _hmax = 0;
	{
		if (_x > 0) then {
			private _n = (_x - _rs) max 0;
			_v setHitIndex [_forEachIndex, _n];
			_hmax = _hmax max _n;
		};
	} forEach _hd;
	if (_hmax <= 0 && {(damage _v) > 0}) then {_v setDamage 0};
};

if (!isServer) exitWith {};

//--- ===================================== SERVIDOR =====================================

VIOC_AF_fnc_p0 = {
	private _p = if (_this isEqualType objNull) then {getPosATL _this} else {_this};
	[_p select 0, _p select 1, 0]
};

VIOC_AF_fnc_roofFree = {
	params ["_p"];
	(lineIntersectsSurfaces [(AGLToASL _p) vectorAdd [0, 0, 0.5], (AGLToASL _p) vectorAdd [0, 0, 40], objNull, objNull, false, 1, "GEOM", "NONE"]) isEqualTo []
};

//--- [p, [ils, eje, largo], ancho] -> true si p esta en la franja de la pista.
VIOC_AF_fnc_onRunway = {
	params ["_p", "_rwy", "_lat"];
	if (count _rwy < 3) exitWith {false};
	_rwy params ["_ils", "_ax", "_len"];
	private _dx = (_p select 0) - (_ils select 0);
	private _dy = (_p select 1) - (_ils select 1);
	private _t = (_dx * (_ax select 0)) + (_dy * (_ax select 1));
	private _l = abs ((_dx * (_ax select 1)) - (_dy * (_ax select 0)));
	(_t > -300) && {_t < (_len + 300)} && {_l < _lat}
};

//--- [p, a, b] -> distancia 2D de p al segmento a-b.
VIOC_AF_fnc_distSeg = {
	params ["_p", "_a", "_b"];
	private _abx = (_b select 0) - (_a select 0);
	private _aby = (_b select 1) - (_a select 1);
	private _l2 = (_abx * _abx) + (_aby * _aby);
	private _t = if (_l2 < 0.01) then {0} else {((((_p select 0) - (_a select 0)) * _abx) + (((_p select 1) - (_a select 1)) * _aby)) / _l2};
	_t = (_t max 0) min 1;
	_p distance2D [(_a select 0) + (_abx * _t), (_a select 1) + (_aby * _t), 0]
};

//--- [posicion, lado, radio] -> unidades y vehiculos con dotacion de los otros bandos (tambien la guerrilla).
VIOC_AF_fnc_enemies = {
	params ["_pos", "_side", "_r"];
	private _en = [west, east, resistance] - [_side];
	((_pos call VIOC_AF_fnc_p0) nearEntities [["Man", "Car", "Motorcycle", "Tank", "Air", "Ship", "StaticWeapon"], _r]) select {alive _x && {(side _x) in _en}}
};

VIOC_AF_fnc_safe = {
	params ["_pos", "_side", "_r"];
	private _near = (_pos call VIOC_AF_fnc_p0) nearEntities [["Man", "Car", "Motorcycle", "Tank", "Air", "Ship", "StaticWeapon"], _r];
	private _n = 0;
	{ _n = _n + (_x countSide _near) } forEach ([west, east, resistance] - [_side]);
	_n == 0
};

//--- [objeto muerto] -> al recolector de basura de la mision (CTI_SE_FNC_TrashObject, que perf_cleanup tambien usa), una vez.
VIOC_AF_fnc_trash = {
	params ["_o"];
	if (isNull _o || {_o getVariable ["vioc_af_trashed", false]}) exitWith {};
	_o setVariable ["vioc_af_trashed", true];
	if (!isNil "CTI_SE_FNC_TrashObject") then {[_o] spawn CTI_SE_FNC_TrashObject};
};

VIOC_AF_fnc_humans = {
	(allPlayers - (entities "HeadlessClient_F"))
};

VIOC_AF_fnc_playersNear = {
	params ["_p", "_r"];
	((call VIOC_AF_fnc_humans) findIf {alive _x && {(_x distance2D _p) < _r}}) >= 0
};

VIOC_AF_fnc_playerSides = {
	private _res = [];
	{ private _s = side group _x; if !(_s in _res) then {_res pushBack _s} } forEach (call VIOC_AF_fnc_humans);
	_res
};

//--- [IA que se van a crear] -> true si cabe en el presupuesto de IA (perf_cleanup, si esta).
VIOC_AF_fnc_budget = {
	params [["_need", 0]];
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", VIOC_AF_AI_MAX_DEFAULT];
	if !(_max isEqualType 0) then {_max = VIOC_AF_AI_MAX_DEFAULT};
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
	if (!(_cnt isEqualType 0) || {_cnt < 0}) then {_cnt = {!isPlayer _x} count allUnits};
	(_cnt + _need) <= _max
};

//--- [aeronave] -> fraccion de municion util (sin bengalas) frente a la referencia guardada de esa aeronave (1 si no lleva armas).
VIOC_AF_fnc_ammoRatio = {
	params ["_v"];
	private _have = 0;
	private _all = 0;
	{
		_x params ["_mag", "_tp", "_cnt"];
		private _ammo = getText (configFile >> "CfgMagazines" >> _mag >> "ammo");
		if ((getText (configFile >> "CfgAmmo" >> _ammo >> "simulation")) != "shotCM") then {
			private _max = getNumber (configFile >> "CfgMagazines" >> _mag >> "count");
			if (_max > 0) then {_have = _have + (_cnt min _max); _all = _all + _max};
		};
	} forEach (magazinesAllTurrets _v);
	private _full = _v getVariable ["vioc_af_full", -1];
	if (_full < _all) then {_full = _all; _v setVariable ["vioc_af_full", _full]};
	if (_full <= 0) exitWith {1};
	_have / _full
};

//--- [clase] -> radio en m para buscar lugar. sizeOf da 0 si ese modelo aun no se cargo: entonces mapSize del config y un
//--- minimo por tipo (helicoptero 15, avion 20, vehiculo 6).
VIOC_AF_fnc_radius = {
	params ["_class"];
	private _kind = switch (true) do {case (_class isKindOf "Plane"): {0}; case (_class isKindOf "Helicopter"): {1}; case (_class isKindOf "Man"): {3}; default {2}};
	private _s = sizeOf _class;
	if (_s > 0) exitWith {(_s / 2) max ([8, 6, 3, 0.5] select _kind)};
	((getNumber (configFile >> "CfgVehicles" >> _class >> "mapSize")) / 2) max ([20, 15, 6, 0.5] select _kind)
};

//--- Lugar libre para un helicoptero (vacio o que aterriza): claro plano, sin arboles, edificios ni vehiculos, fuera de la pista.
//--- [ancla, clase, pista, radio min, radio max] -> [lugar, direccion] o []. Nunca devuelve el ancla misma.
VIOC_AF_fnc_spotHeli = {
	params ["_anchor", "_class", "_rwy", ["_rmin", 20], ["_rmax", 130]];
	private _a = _anchor call VIOC_AF_fnc_p0;
	private _r = [_class] call VIOC_AF_fnc_radius;
	private _res = [];
	for "_i" from 1 to 12 do {
		private _c = _a getPos [_rmin + random (_rmax - _rmin), random 360];
		private _p = _c findEmptyPosition [0, 40, _class];
		if (count _p > 1) then {
			_p = [_p select 0, _p select 1, 0];
			if (!(surfaceIsWater _p)
				&& {(_p distance2D _a) < (_rmax + 70)}
				&& {!([_p, _rwy, 70] call VIOC_AF_fnc_onRunway)}
				&& {count (_p isFlatEmpty [-1, -1, 0.25, _r, 0, false, objNull]) > 0}
				&& {(nearestTerrainObjects [_p, ["TREE", "SMALL TREE", "BUSH", "BUILDING", "HOUSE", "ROCK", "ROCKS", "WALL", "FENCE", "POWER LINES", "TRANSMITTER", "RUIN", "BUNKER", "FORTRESS", "VIEW-TOWER", "WATERTOWER", "LIGHTHOUSE", "CHURCH", "CHAPEL", "CROSS", "FUELSTATION", "HOSPITAL", "STACK", "QUAY"], _r + 4, false, true]) isEqualTo []}
				&& {(_p nearEntities [["AllVehicles"], _r + 6]) isEqualTo []}
				&& {[_p] call VIOC_AF_fnc_roofFree}) then {
				_res = [_p, _a getDir _p];
			};
		};
		if (count _res > 0) exitWith {};
	};
	_res
};

//--- Aviones vacios: lugares de estacionamiento junto al rodaje (no en el), fuera de la pista. Se generan desplazando cada punto de
//--- rodaje en perpendicular a la pista, hacia el lado contrario a ella (r+10, r+25, r+40 m), empezando por el final de la plataforma.
//--- Se descartan: la franja de la pista (35 m + r del eje), cerca de un tramo de rodaje (r + 8 m), y a menos de max(40, r + 25) m
//--- del ultimo punto de salida de pista (donde paran los aviones de landAt) y de los 2 primeros de entrada (inicio del rodaje de despegue).
//--- Los puntos que estan sobre la pista (salidas de pista) se desplazan hacia el lado del rodaje y la plataforma. Los candidatos
//--- se ordenan por distancia a la plataforma (_ref), para preferir estacionar alli.
//--- [rodaje de salida, rodaje de entrada, pista, radio, plataforma] -> [[lugar, direccion], ...] (solo geometria).
VIOC_AF_fnc_planeCands = {
	params ["_off", "_in", "_rwy", "_r", ["_ref", []]];
	if (count _rwy < 3 || {(count _off) + (count _in) == 0}) exitWith {[]};
	_rwy params ["_ils", "_ax", "_len"];
	private _perp = [-(_ax select 1), _ax select 0];
	private _segs = [];
	{
		private _l = _x;
		for "_i" from 0 to ((count _l) - 2) do {_segs pushBack [_l select _i, _l select (_i + 1)]};
	} forEach [_off, _in];
	private _keep = [];
	if (count _off > 0) then {_keep pushBack (_off select ((count _off) - 1))};
	{ if (_forEachIndex < 2) then {_keep pushBack _x} } forEach _in;
	private _clear = (_r + 25) max 40;
	private _pts = (+_off);
	reverse _pts;
	_pts append _in;
	private _fnc_lat = {(((_this select 0) - (_ils select 0)) * (_perp select 0)) + (((_this select 1) - (_ils select 1)) * (_perp select 1))};
	private _side0 = 0;
	{ private _l = _x call _fnc_lat; if ((abs _l) >= 15) then {_side0 = _side0 + _l} } forEach _pts;
	_side0 = [1, -1] select (_side0 < 0);
	private _res = [];
	{
		private _q = _x;
		private _lat = _q call _fnc_lat;
		private _sg = if ((abs _lat) < 15) then {_side0} else {[1, -1] select (_lat < 0)};
		{
			private _c = [(_q select 0) + ((_perp select 0) * _sg * _x), (_q select 1) + ((_perp select 1) * _sg * _x), 0];
			if (!([_c, _rwy, 35 + _r] call VIOC_AF_fnc_onRunway)
				&& {(_segs findIf {([_c, _x select 0, _x select 1] call VIOC_AF_fnc_distSeg) < (_r + 8)}) < 0}
				&& {(_keep findIf {(_x distance2D _c) < _clear}) < 0}
				&& {(_res findIf {((_x select 0) distance2D _c) < ((2 * _r) + 4)}) < 0}) then {
				_res pushBack [_c, _c getDir _q]; //--- mirando hacia el rodaje
			};
		} forEach [_r + 10, _r + 25, _r + 40];
	} forEach _pts;
	if (count _ref > 1) then {
		private _keys = _res apply {[(_x select 0) distance2D _ref, _x]};
		_keys sort true;
		_res = _keys apply {_x select 1};
	};
	_res
};

//--- [lugar, radio, mirar vehiculos] -> true si el lugar sirve: tierra, plano, sin objetos del mapa, sin vehiculos, sin techo.
VIOC_AF_fnc_planeFree = {
	params ["_c", "_r", ["_veh", true]];
	!(surfaceIsWater _c)
	&& {count (_c isFlatEmpty [-1, -1, 0.2, _r, 0, false, objNull]) > 0}
	&& {(nearestTerrainObjects [_c, ["TREE", "SMALL TREE", "BUSH", "BUILDING", "HOUSE", "ROCK", "ROCKS", "WALL", "FENCE", "POWER LINES", "TRANSMITTER", "RUIN", "BUNKER", "FORTRESS", "VIEW-TOWER", "WATERTOWER", "LIGHTHOUSE", "CHURCH", "CHAPEL", "CROSS", "FUELSTATION", "HOSPITAL", "STACK", "QUAY"], _r + 2, false, true]) isEqualTo []}
	&& {!_veh || {(_c nearEntities [["AllVehicles"], _r + 4]) isEqualTo []}}
	&& {[_c] call VIOC_AF_fnc_roofFree}
};

//--- [rodaje de salida, rodaje de entrada, clase, pista] -> [lugar, direccion] o [].
VIOC_AF_fnc_spotPlane = {
	params ["_off", "_in", "_class", "_rwy", ["_ref", []]];
	private _r = [_class] call VIOC_AF_fnc_radius;
	private _res = [];
	{
		if ([_x select 0, _r] call VIOC_AF_fnc_planeFree) exitWith {_res = +_x};
	} forEach ([_off, _in, _rwy, _r, _ref] call VIOC_AF_fnc_planeCands);
	_res
};

//--- [punto, pista, puntos del aerodromo] -> el punto, o si esta en la franja de la pista, el mismo punto llevado a 70 m del eje hacia el
//--- lado del rodaje (o el otro lado si alli hay agua). Asi la "plataforma" nunca queda sobre la pista.
VIOC_AF_fnc_besideRunway = {
	params ["_p", "_rwy", "_pts"];
	if !([_p, _rwy, 40] call VIOC_AF_fnc_onRunway) exitWith {_p};
	_rwy params ["_ils", "_ax"];
	private _perp = [-(_ax select 1), _ax select 0];
	private _fl = {(((_this select 0) - (_ils select 0)) * (_perp select 0)) + (((_this select 1) - (_ils select 1)) * (_perp select 1))};
	private _sum = 0;
	{ _sum = _sum + (_x call _fl) } forEach _pts;
	private _sg = [1, -1] select (_sum < 0);
	private _res = _p;
	{
		private _d = (_sg * _x * 70) - (_p call _fl);
		private _q = [(_p select 0) + ((_perp select 0) * _d), (_p select 1) + ((_perp select 1) * _d), 0];
		if !(surfaceIsWater _q) exitWith {_res = _q};
	} forEach [1, -1];
	_res
};

//--- Tabla de aerodromos (HashMaps). Necesita CTI_Towns.
VIOC_AF_fnc_buildTable = {
	private _wcfg = configFile >> "CfgWorlds" >> worldName;
	private _cfgs = [_wcfg];
	if (isClass (_wcfg >> "SecondaryAirports")) then {_cfgs append ("true" configClasses (_wcfg >> "SecondaryAirports"))};
	private _ids = [];
	private _aa = allAirports;
	if (!isNil "_aa" && {_aa isEqualType []} && {count _aa > 0} && {(_aa select 0) isEqualType []}) then {_ids = _aa select 0};
	private _fnc_in = {(_this select 0) isEqualType 0 && {(_this select 1) isEqualType 0} && {(_this select 0) > 0} && {(_this select 1) > 0} && {(_this select 0) < worldSize} && {(_this select 1) < worldSize}};
	private _tab = [];
	{
		private _c = _x;
		private _i = _forEachIndex;
		private _ils = getArray (_c >> "ilsPosition");
		if (count _ils > 1 && {_ils call _fnc_in}) then {
