		!(surfaceIsWater _q) && {!(isOnRoad _q)} && {(_q distance2D _tc) <= VIOC_AF_DEF_RANGE}
		&& {!([_q, _rwy, 90] call VIOC_AF_fnc_onRunway)}
		&& {(_segs findIf {([_q, _x select 0, _x select 1] call VIOC_AF_fnc_distSeg) < 55}) < 0}
		&& {(_pts findIf {(_x distance2D _q) < 55}) < 0}
		&& {(_chosen findIf {((_x select 0) distance2D _q) < 70}) < 0}
		&& {(_other findIf {(_x distance2D _q) < 30}) < 0}
		&& {count (_q isFlatEmpty [-1, -1, 0.3, 3, 0, false, objNull]) > 0}
		&& {[_q] call VIOC_AF_fnc_roofFree}
	};
	private _fnc_pick = {
		params ["_cands", "_kinds"];
		private _done = false;
		{
			private _q = _x findEmptyPosition [0, 25, "I_static_AA_F"];
			if (count _q > 1) then {_q = [_q select 0, _q select 1, 0]};
			if (count _q > 1 && {[_q] call _fnc_ok}) exitWith {_chosen pushBack [_q, _tc getDir _q, _kinds]; _done = true};
		} forEach _cands;
		_done
	};
	private _fnc_end = {
		params ["_t"];
		private _r = [];
		{
			private _s = _x;
			{ _r pushBack [(_ils select 0) + ((_ax select 0) * _t) + ((_perp select 0) * _s * _x), (_ils select 1) + ((_ax select 1) * _t) + ((_perp select 1) * _s * _x), 0] } forEach [130, 170, 220];
		} forEach [1, -1];
		_r
	};
	private _apron = _af get "apron";
	private _ap = [];
	for "_i" from 0 to 7 do {_ap pushBack (_apron getPos [70 + random 40, (_i * 45) + random 20])};
	private _mid = [_len * 0.5] call _fnc_end;
	if !([[0] call _fnc_end, ["VIOC_AA", "AA"]] call _fnc_pick) then {[_mid + _ap, ["VIOC_AA", "AA"]] call _fnc_pick};
	if !([[_len] call _fnc_end, ["VIOC_AA", "AA"]] call _fnc_pick) then {[_mid + _ap, ["VIOC_AA", "AA"]] call _fnc_pick};
	[_ap, ["VIOC_AT", "AT"]] call _fnc_pick;
	[_ap + _mid, ["MG"]] call _fnc_pick;
	_chosen
};

VIOC_AF_fnc_defenses = {
