};

//--- ---------------------------------- 5) Estacionadas ----------------------------------
//--- [lado] -> [helicopteros, aviones] que ese lado puede tener (cacheado por nivel de mejora aerea).
VIOC_AF_fnc_parkClasses = {
	params ["_side"];
	private _key = str _side;
	private _lvl = -1;
	if (_side == west || {_side == east}) then {
		private _u = (_side) call CTI_CO_FNC_GetSideUpgrades;
		if (!isNil "_u" && {_u isEqualType []} && {count _u > CTI_UPGRADE_AIR}) then {_lvl = _u select CTI_UPGRADE_AIR};
	};
	private _cache = VIOC_AF_CLS getOrDefault [_key, [-99, [], []]];
	if ((_cache select 0) == _lvl) exitWith {[_cache select 1, _cache select 2]};
	private _h = [];
	private _pl = [];
	private _fnc_add = {
		params ["_cls"];
		if (!isNil "VIOC_CA_fnc_banned" && {[_cls] call VIOC_CA_fnc_banned}) exitWith {}; //--- VIOC contemporary_assets: nunca estacionar un avion prohibido (2035 / 2a Guerra Mundial)
		if (_cls isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _cls)} && {getNumber (configFile >> "CfgVehicles" >> _cls >> "isUav") != 1} && {getNumber (configFile >> "CfgVehicles" >> _cls >> "scope") >= 1}) then {
			if (_cls isKindOf "Helicopter") then {_h pushBackUnique _cls} else {if (_cls isKindOf "Plane") then {_pl pushBackUnique _cls}};
		};
	};
	if (_side == west || {_side == east}) then {
		{
			private _var = missionNamespace getVariable [_x, []];
			if (_var isEqualType [] && {count _var > CTI_UNIT_SCRIPTS}) then {
				private _model = _x;
				private _sc = _var select CTI_UNIT_SCRIPTS;
				if (_sc isEqualType [] && {count _sc > 0}) then {_model = _sc select 0};
				if (((_var select CTI_UNIT_UPGRADE) isEqualType 0) && {(_var select CTI_UNIT_UPGRADE) <= _lvl}) then {[_model] call _fnc_add};
			};
		} forEach (missionNamespace getVariable [format ["CTI_%1_%2Units", _side, CTI_AIR], []]);
	} else {
		//--- Guerrilla: sus listas aereas de pueblo; si estan vacias, las aeronaves de su faccion (la de su infanteria); si no hay, nada.
		{
			{ if (_x isEqualType [] && {count _x > 0}) then {[_x select 0] call _fnc_add} else {[_x] call _fnc_add} } forEach (missionNamespace getVariable [_x, []]);
		} forEach ["GUER_AIR_SQ_FIGHTER", "GUER_AIR_SQ_BOMBER"];
		if ((count _h) + (count _pl) == 0) then {
			private _inf = missionNamespace getVariable ["GUER_INFANTRY_SQ_LIGHT", []];
			private _fac = "";
			if (_inf isEqualType [] && {count _inf > 0}) then {
				private _c = _inf select 0;
				if (_c isEqualType []) then {_c = _c param [0, ""]};
				if (_c isEqualType "") then {_fac = getText (configFile >> "CfgVehicles" >> _c >> "faction")};
			};
			if (_fac != "") then {
				{ if (getText (_x >> "faction") == _fac) then {[configName _x] call _fnc_add} } forEach ("getNumber (_x >> 'scope') == 2 && {(configName _x) isKindOf 'Air'}" configClasses (configFile >> "CfgVehicles"));
			};
		};
	};
	VIOC_AF_CLS set [_key, [_lvl, _h, _pl]];
	[_h, _pl]
};

//--- [indice, forzar] -> "ok" o el motivo por el que no aparecio.
VIOC_AF_fnc_parkSpawn = {
	params ["_k", ["_force", false]];
	private _af = VIOC_AF_TABLE select _k;
	private _sid = _af get "owner";
	if !(_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID} || {_sid == CTI_RESISTANCE_ID}) exitWith {"sin duenio"};
	private _side = (_sid) call CTI_CO_FNC_GetSideFromID;
	private _mine = VIOC_AF_PARKLIST select {((_x select 1) == _k) && {alive (_x select 0)}};
	private _nh = {(_x select 3) == "heli"} count _mine;
	private _np = {(_x select 3) == "plane"} count _mine;
	private _cap = if (_af get "main") then {VIOC_AF_PARK_MAIN} else {VIOC_AF_PARK_OTHER};
	if (!_force && {({alive (_x select 0)} count VIOC_AF_PARKLIST) >= VIOC_AF_PARK_TOTAL}) exitWith {"tope total"};
	private _cls = [_side] call VIOC_AF_fnc_parkClasses;
	private _kinds = [];
	if ((_force || {_np < (_cap select 1)}) && {count (_cls select 1) > 0} && {_af get "planeOk"}) then {_kinds pushBack "plane"};
	if ((_force || {_nh < (_cap select 0)}) && {count (_cls select 0) > 0} && {_force || {time >= (_af get "noHeliUntil")}}) then {_kinds pushBack "heli"};
	if (count _kinds == 0) exitWith {"lleno o sin clases"};
	private _kind = selectRandom _kinds;
	private _list = if (_kind == "plane") then {_cls select 1} else {_cls select 0};
	private _res = "sin lugar libre";
	for "_try" from 1 to 3 do {
		private _c = selectRandom _list;
		private _spot = if (_kind == "plane") then {[_af get "taxiOff", _af get "taxiIn", _c, _af get "rwy", _af get "apron"] call VIOC_AF_fnc_spotPlane} else {[_af get "apron", _c, _af get "rwy"] call VIOC_AF_fnc_spotHeli};
		if (count _spot > 1) exitWith {
			private _p = _spot select 0;
			if (!_force && {[_p, VIOC_AF_PARK_PLAYER_RANGE] call VIOC_AF_fnc_playersNear}) exitWith {_res = "jugador cerca"};
			if (!_force && {!([_p, _side, VIOC_AF_PARK_ENEMY_RANGE] call VIOC_AF_fnc_safe)}) exitWith {_res = "enemigos cerca"};
			private _v = createVehicle [_c, _p, [], 0, "NONE"];
			if (isNull _v) exitWith {_res = "createVehicle fallo"};
			_v setDir (_spot select 1);
			_v setVariable ["VIOC_AF_parked", true, true];
			_v lock 2;
			clearItemCargoGlobal _v;
			clearMagazineCargoGlobal _v;
			clearWeaponCargoGlobal _v;
			clearBackpackCargoGlobal _v;
			[_v, _side] call CTI_CO_FNC_SanitizeAircraft;
			_v enableDynamicSimulation true;
			if (!isNil "VIOC_ZEUS" && {VIOC_ZEUS isEqualType objNull} && {!isNull VIOC_ZEUS}) then {VIOC_ZEUS addCuratorEditableObjects [[_v], true]};
			VIOC_AF_PARKLIST pushBack [_v, _k, _sid, _kind, time, -1];
			_af set [["failHeli", "failPlane"] select (_kind == "plane"), 0];
			VIOC_AF_INFO set [3, (VIOC_AF_INFO select 3) + 1];
			diag_log format ["[VIOC airfields] estacionada %1 de %2 en %3", _c, _side, _af get "name"];
			_res = "ok";
		};
	};
	//--- Sin lugar 3 veces seguidas: los aviones se dejan para siempre en ese aerodromo, los helicopteros 1 h (nada de reintentos sin fin).
	if (_res == "sin lugar libre") then {
		private _key = ["failHeli", "failPlane"] select (_kind == "plane");
		_af set [_key, (_af get _key) + 1];
		if ((_af get _key) >= 3) then {
			_af set [_key, 0];
			if (_kind == "plane") then {_af set ["planeOk", false]} else {_af set ["noHeliUntil", time + 3600]};
			diag_log format ["[VIOC airfields] %1: sin lugar para %2 estacionados, se deja de intentar", _af get "name", _kind];
		};
	};
	_res
};

//--- [indice, nuevo duenio] -> las estacionadas del duenio anterior se borran (o quedan inutiles y se borran sin jugadores cerca).
VIOC_AF_fnc_parkOwnerChanged = {
	params ["_k", "_sid"];
	{
		_x params ["_v", "_kk", "_psid"];
		if (_kk == _k && {_psid != _sid} && {alive _v} && {({alive _x} count (crew _v)) == 0}) then {
			if ([_v, 300] call VIOC_AF_fnc_playersNear) then {
				_v setVariable ["vioc_af_doomed", true];
				_v lock 2;
				if (local _v) then {_v setFuel 0} else {[_v, 0] remoteExec ["setFuel", _v]};
