};

VIOC_AF_fnc_parkTick = {
	{
		private _e = _x;
		_e params ["_v", "_k", "_sid", "_kind", "_t", "_tDead"];
		if (isNull _v) then {VIOC_AF_PARKLIST set [_forEachIndex, -1]} else {
			if (!alive _v) then {
