				if ((time - (_e select 5)) > 600 && {!([_v, 1000] call VIOC_AF_fnc_playersNear)}) then {deleteVehicle _v; VIOC_AF_PARKLIST set [_forEachIndex, -1]};
			} else {
				if (({alive _x} count (crew _v)) > 0) then {
					_v setVariable ["VIOC_AF_parked", false, true]; //--- alguien la ocupo (Zeus): deja de ser estacionada
					VIOC_AF_PARKLIST set [_forEachIndex, -1];
				} else {
					if ((_v getVariable ["vioc_af_doomed", false]) && {!([_v, 300] call VIOC_AF_fnc_playersNear)}) then {
						deleteVehicle _v;
						VIOC_AF_INFO set [4, (VIOC_AF_INFO select 4) + 1];
						VIOC_AF_PARKLIST set [_forEachIndex, -1];
					};
				};
			};
		};
	} forEach VIOC_AF_PARKLIST;
	VIOC_AF_PARKLIST = VIOC_AF_PARKLIST - [-1];
	if !([0] call VIOC_AF_fnc_budget) exitWith {};
	private _ps = call VIOC_AF_fnc_playerSides;
	{
		private _af = _x;
		private _sid = _af get "owner";
		if ((_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID} || {_sid == CTI_RESISTANCE_ID}) && {!(((_sid) call CTI_CO_FNC_GetSideFromID) in _ps)} && {time >= (_af get "nextPark")}) then {
			private _r = [_forEachIndex, false] call VIOC_AF_fnc_parkSpawn;
			switch (_r) do {
				case "ok": {_af set ["nextPark", time + ([60, VIOC_AF_PARK_REFILL] select (_af get "filled"))]};
				case "lleno o sin clases": {_af set ["filled", true]; _af set ["nextPark", time + VIOC_AF_PARK_REFILL]};
				default {_af set ["nextPark", time + 120]};
			};
		};
	} forEach VIOC_AF_TABLE;
};

//--- ---------------------------------- 6) Alerta ----------------------------------
//--- [indice, objetivo (objeto o posicion), forzar] -> "ok" o el motivo.
VIOC_AF_fnc_scrStart = {
	params ["_k", "_tgt", ["_force", false]];
	private _af = VIOC_AF_TABLE select _k;
	private _sid = _af get "owner";
	if !(_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID} || {_sid == CTI_RESISTANCE_ID}) exitWith {"sin duenio"};
	private _side = (_sid) call CTI_CO_FNC_GetSideFromID;
	private _cands = VIOC_AF_PARKLIST select {((_x select 1) == _k) && {(_x select 3) == "heli"} && {(_x select 2) == _sid} && {alive (_x select 0)} && {!((_x select 0) getVariable ["vioc_af_doomed", false])}};
	if (count _cands == 0) exitWith {"no hay helicoptero estacionado"};
	private _e = _cands select 0;
	{
		private _armed = ((magazinesAllTurrets (_x select 0)) findIf {(getText (configFile >> "CfgAmmo" >> (getText (configFile >> "CfgMagazines" >> (_x select 0) >> "ammo")) >> "simulation")) != "shotCM"}) >= 0;
		if (_armed) exitWith {_e = _x};
	} forEach _cands;
	private _v = _e select 0;
	_af set ["scrCd", time + VIOC_AF_SCR_COOLDOWN];
	createVehicleCrew _v;
	private _crew = crew _v;
	if (count _crew == 0 || {isNull (driver _v)} || {(side group (driver _v)) != _side}) exitWith {
		private _cg = if (count _crew > 0) then {group (_crew select 0)} else {grpNull};
		{ _v deleteVehicleCrew _x } forEach _crew;
		[_cg] spawn {params ["_g"]; sleep 5; if (!isNull _g && {({alive _x} count (units _g)) == 0}) then {{deleteVehicle _x} forEach (units _g); deleteGroup _g}};
		"la tripulacion del config no es del bando"
	};
	private _g = group (driver _v);
	VIOC_AF_PARKLIST = VIOC_AF_PARKLIST - [_e];
	_v setVariable ["VIOC_AF_parked", false, true];
	_v setVariable ["vioc_af_scramble", true, true];
	_g setVariable ["vioc_af_scramble", true];
	_v lock 0;
	_v setFuel 1;
	_v setVariable ["vioc_af_landcmd", false];
	_g setBehaviour "AWARE";
	_g setCombatMode "RED";
	_v flyInHeight 80;
	private _tp = if (_tgt isEqualType objNull) then {_tgt call VIOC_AF_fnc_p0} else {_tgt};
	_g move _tp;
	if (!isNil "VIOC_ZEUS" && {VIOC_ZEUS isEqualType objNull} && {!isNull VIOC_ZEUS}) then {VIOC_ZEUS addCuratorEditableObjects [crew _v, true]};
	VIOC_AF_SCR pushBack [_v, _g, _k, time, "attack", time, _tp, _sid];
	VIOC_AF_INFO set [5, (VIOC_AF_INFO select 5) + 1];
	diag_log format ["[VIOC airfields] alerta en %1: despega %2 de %3", _af get "name", typeOf _v, _side];
	"ok"
};

VIOC_AF_fnc_scrTick = {
	{
		private _e = _x;
		_e params ["_v", "_g", "_k", "_t0", "_stage", "_tE", "_tp", "_sid"];
		private _af = VIOC_AF_TABLE select _k;
		private _apron = _af get "apron";
		private _end = false;
		private _live = if (isNull _g) then {[]} else {(units _g) select {alive _x}};
		if (!alive _v || {count _live == 0} || {({alive _x} count (crew _v)) == 0}) then {
			//--- Derribado o sin tripulacion: el resto va al recolector de la mision; la aeronave vacia queda cerrada y se borra sin
			//--- jugadores cerca; la tripulacion (viva o muerta) queda en VIOC_AF_LEFTOVER hasta que se pueda borrar.
			if (!isNull _v && {!alive _v}) then {[_v] call VIOC_AF_fnc_trash};
			if (alive _v && {({alive _x} count (crew _v)) == 0}) then {
				_v lock 2;
				_v setVariable ["vioc_af_doomed", true];
				_v setVariable ["VIOC_AF_parked", true, true];
				VIOC_AF_PARKLIST pushBack [_v, _k, -1, "heli", time, -1];
			};
			if (!isNull _g) then {{VIOC_AF_LEFTOVER pushBack [_x, time]} forEach (units _g); VIOC_AF_LEFTOVER pushBack [_g, time]};
			_end = true;
		} else {
			if (_stage == "attack") then {
				private _en = [_apron, side _g, VIOC_AF_SCR_RANGE + 300] call VIOC_AF_fnc_enemies;
				if (count _en > 0) then {
					_e set [5, time];
					private _p = (_en select 0) call VIOC_AF_fnc_p0;
					if ((_p distance2D _tp) > 200) then {_g move _p; _e set [6, _p]};
				};
				if ((time - _t0) > VIOC_AF_SCR_TIME || {(time - (_e select 5)) > 120}) then {_e set [4, "return"]; _e set [3, time]; _g move _apron; _v flyInHeight 100};
			} else {
				if (!(_v getVariable ["vioc_af_landcmd", false]) && {(_v distance2D _apron) < 600}) then {_v land "LAND"; _v setVariable ["vioc_af_landcmd", true]};
				private _down = (isTouchingGround _v) || {((getPosATL _v) select 2) < 2};
				if ((_down || {(time - _t0) > 400}) && {!([_v, 1000] call VIOC_AF_fnc_playersNear)}) then {
					{ _v deleteVehicleCrew _x } forEach (crew _v);
					{ if (alive _x) then {deleteVehicle _x} } forEach (units _g);
					[_g] spawn {params ["_g"]; sleep 5; if (!isNull _g && {count (units _g) == 0}) then {deleteGroup _g}};
					if (_down && {(_v distance2D _apron) < 400} && {(_af get "owner") == _sid}) then {
						_v lock 2;
						_v setVariable ["VIOC_AF_parked", true, true];
						_v setVariable ["vioc_af_scramble", false, true];
						VIOC_AF_PARKLIST pushBack [_v, _k, _sid, "heli", time, -1];
					} else {deleteVehicle _v};
					_end = true;
				};
			};
		};
		if (_end) then {VIOC_AF_SCR set [_forEachIndex, -1]};
	} forEach VIOC_AF_SCR;
	VIOC_AF_SCR = VIOC_AF_SCR - [-1];
	//--- Tripulaciones sueltas de alertas: vivas, se borran sin jugadores a 1 km; muertas, al recolector; el grupo vacio, borrado.
	{
		_x params ["_o", "_t"];
		if (_o isEqualType grpNull) then {
			if (isNull _o) then {VIOC_AF_LEFTOVER set [_forEachIndex, -1]} else {
				if (({alive _x} count (units _o)) == 0 && {(time - _t) > 10}) then {deleteGroup _o; VIOC_AF_LEFTOVER set [_forEachIndex, -1]};
			};
		} else {
			if (isNull _o) then {VIOC_AF_LEFTOVER set [_forEachIndex, -1]} else {
				if (!alive _o) then {[_o] call VIOC_AF_fnc_trash; VIOC_AF_LEFTOVER set [_forEachIndex, -1]} else {
					if (vehicle _o == _o && {!([_o, 1000] call VIOC_AF_fnc_playersNear)}) then {deleteVehicle _o; VIOC_AF_LEFTOVER set [_forEachIndex, -1]};
				};
			};
		};
	} forEach VIOC_AF_LEFTOVER;
	VIOC_AF_LEFTOVER = VIOC_AF_LEFTOVER - [-1];
	//--- Nuevas alertas.
	if (({alive (_x select 0)} count VIOC_AF_SCR) >= VIOC_AF_SCR_MAX) exitWith {};
	if !([3] call VIOC_AF_fnc_budget) exitWith {};
	private _ps = call VIOC_AF_fnc_playerSides;
	{
		private _af = _x;
		private _k = _forEachIndex;
		private _sid = _af get "owner";
		if ((_sid == CTI_WEST_ID || {_sid == CTI_EAST_ID} || {_sid == CTI_RESISTANCE_ID}) && {time >= (_af get "scrCd")} && {(VIOC_AF_SCR findIf {(_x select 2) == _k}) < 0}
			&& {(VIOC_AF_PARKLIST findIf {((_x select 1) == _k) && {(_x select 3) == "heli"}}) >= 0}) then {
			private _side = (_sid) call CTI_CO_FNC_GetSideFromID;
			if !(_side in _ps) then {
				private _en = [_af get "apron", _side, VIOC_AF_SCR_RANGE] call VIOC_AF_fnc_enemies;
				private _town = _af get "town";
				private _active = (!isNull _town) && {(_town getVariable ["cti_town_occupation_active", false]) || {_town getVariable ["cti_town_resistance_active", false]}};
				if (count _en >= VIOC_AF_SCR_ENEMIES || {_active && {count _en > 0}}) then {[_k, _en select 0] call VIOC_AF_fnc_scrStart};
			};
		};
	} forEach VIOC_AF_TABLE;
};

//--- ---------------------------------- Consola ----------------------------------
VIOC_AF_fnc_info = {
	private _nl = toString [10];
	private _txt = format ["Aerodromos de %1: servicio %2, defensas %3, estacionadas %4. allAirports %5. INFO %6", worldName,
		missionNamespace getVariable ["VIOC_AIRFIELDS", 1], missionNamespace getVariable ["VIOC_AF_DEFENSES", 1], missionNamespace getVariable ["VIOC_AF_PARKED", 2], allAirports, VIOC_AF_INFO];
	if (isNil "VIOC_AF_TABLE") exitWith {_txt + _nl + "(la tabla todavia no se construyo)"};
	{
		private _k = _forEachIndex;
		_txt = _txt + _nl + format ["#%1 %2 [%3] landAt %4 | duenio %5 | pueblo %6 | pista %7 m | estacionadas %8 | defensas %9 | proxima %10 s | aviones %11",
			_k, _x get "name", _x get "cls", [_k] call VIOC_AF_fnc_landId, _x get "owner",
			if (isNull (_x get "town")) then {"-"} else {round ((_x get "town") distance2D (_x get "ils"))},
			round ((_x get "rwy") select 2), {(_x select 1) == _k && {alive (_x select 0)}} count VIOC_AF_PARKLIST, count (_x get "defs"),
			round (((_x get "nextPark") - time) max 0), ["no", "si"] select (_x get "planeOk")];
	} forEach VIOC_AF_TABLE;
	_txt = _txt + _nl + format ["Regresos a base: %1", VIOC_AF_RTB apply {[typeOf (_x select 1), _x select 8, _x select 12]}];
	_txt = _txt + _nl + format ["Alertas: %1; IDs vistos: %2", VIOC_AF_SCR apply {[typeOf (_x select 0), _x select 4]}, VIOC_AF_IDSEEN];
	diag_log _txt;
	_txt
};

VIOC_AF_fnc_forceParked = {
	params [["_k", 0]];
	if (isNil "VIOC_AF_TABLE" || {_k < 0} || {_k >= count VIOC_AF_TABLE}) exitWith {"no existe ese aerodromo"};
	[_k, true] call VIOC_AF_fnc_parkSpawn
};

VIOC_AF_fnc_forceRTB = {
	params [["_v", objNull]];
	if (isNil "VIOC_AF_TABLE") exitWith {"la tabla todavia no se construyo"};
	if (isNull _v || {!(_v isKindOf "Air")} || {!alive (driver _v)}) exitWith {"no es una aeronave con piloto"};
	private _g = group (driver _v);
	if (({isPlayer _x} count (units _g)) > 0) exitWith {"el grupo tiene jugadores: aterriza tu mismo en el aerodromo"};
	if (_g getVariable ["vioc_air_busy", false]) exitWith {"ya esta regresando"};
	if !(local _v) exitWith {"no es local en esta maquina"};
	private _dest = [_v, side _g] call VIOC_AF_fnc_rtbDest;
	if (count _dest < 3) exitWith {"no hay aerodromo propio no disputado (o el avion no tiene ID de landAt)"};
	if ([_g, _v, side _g, _dest, "forzado"] call VIOC_AF_fnc_rtbStart) then {"ok"} else {"no se pudo"}
};

VIOC_AF_fnc_forceScramble = {
	params [["_k", 0]];
	if (isNil "VIOC_AF_TABLE" || {_k < 0} || {_k >= count VIOC_AF_TABLE}) exitWith {"no existe ese aerodromo"};
	private _tgt = if (hasInterface && {!isNull player}) then {vehicle player} else {(VIOC_AF_TABLE select _k) get "ils"};
	[_k, _tgt, true] call VIOC_AF_fnc_scrStart
};

//--- ---------------------------------- Bucle ----------------------------------
VIOC_AF_fnc_serverLoop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	waitUntil {sleep 2; ({isNil {_x getVariable "cti_town_sideID"}} count CTI_Towns) == 0};
	sleep 30; //--- deja que cada pueblo cree sus defensas de la mision primero (Init_Location.sqf)
	VIOC_AF_TABLE = call VIOC_AF_fnc_buildTable;
	if (count VIOC_AF_TABLE == 0) exitWith {diag_log format ["[VIOC airfields] %1 no tiene aeropuertos en CfgWorlds: nada que hacer", worldName]};
	call VIOC_AF_fnc_ownerTick;
	if (call VIOC_AF_fnc_defOn) then {call VIOC_AF_fnc_defenses};
	private _n = 0;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		if (call VIOC_AF_fnc_svcOn) then {call VIOC_AF_fnc_svcTick};
		if ((_n % 3) == 0) then {
			call VIOC_AF_fnc_ownerTick;
			if (call VIOC_AF_fnc_svcOn) then {call VIOC_AF_fnc_rtbTick};
		};
		if ((call VIOC_AF_fnc_parkMode) >= 2 && {(_n % 4) == 1}) then {call VIOC_AF_fnc_scrTick};
		if ((call VIOC_AF_fnc_parkMode) >= 1 && {(_n % 12) == 2}) then {call VIOC_AF_fnc_parkTick};
		_n = _n + 1;
		sleep VIOC_AF_PERIOD;
	};
};

if (isNil "VIOC_AF_RUNNING") then {
	if ((call VIOC_AF_fnc_svcOn) || {call VIOC_AF_fnc_defOn} || {(call VIOC_AF_fnc_parkMode) > 0}) then {
		VIOC_AF_RUNNING = true;
		VIOC_AF_RTB = [];
		VIOC_AF_PARKLIST = [];
		VIOC_AF_SCR = [];
		VIOC_AF_LEFTOVER = [];
		VIOC_AF_IDSEEN = createHashMap;
		VIOC_AF_CLS = createHashMap;
		[] spawn VIOC_AF_fnc_serverLoop;
	} else {
		diag_log "[VIOC airfields] desactivado por los parametros de lobby";
	};
};

